import mq3.client.ui_rankings as r
import mq3.client.ui_qmenu as q
function req(ok,label) if not ok then return error(7992,"rankings: "+label) end if;return 1 end function
function main(args) count=0;count=count+req(r.sanitize("Player99")=="Player99" and r.sanitize("Player-99")=="Player","name validation");s=r.create(false);f=q.item(q.MTYPE_FIELD,"",0,20,30,0);f.buffer="Pass12";f.fieldCursor=6;rows=r.Rankings_DrawPassword(s,f,true,false);count=count+req(f.buffer=="Pass12" and rows[0].text=="*" and len(rows)==7,"password mask restores buffer");f.buffer="Ab!tail";f.fieldCursor=9;r.Rankings_DrawName(s,f,false,false);count=count+req(f.buffer=="Ab" and f.fieldCursor==2,"name draw sanitizes and clamps cursor");r.Rankings_MenuInit(s,r.QGR_STATUS_NEW);count=count+req(len(s.menu.items)==7 and s.frame.name==r.RANKINGS_FRAME and s.login.string=="LOGIN" and s.leave.string=="LEAVE ARENA","original menu layout");count=count+req((s.setup.flags&q.QMF_HIDDEN)!=0 and (s.logout.flags&q.QMF_HIDDEN)!=0,"new status visibility");active=r.create(false);r.Rankings_MenuInit(active,r.QGR_STATUS_ACTIVE);count=count+req((active.login.flags&q.QMF_HIDDEN)!=0 and (active.logout.flags&q.QMF_HIDDEN)==0,"active logout visibility");pending=r.create(false);r.Rankings_MenuInit(pending,r.QGR_STATUS_PENDING);count=count+req((pending.logout.flags&q.QMF_GRAYED)!=0,"pending action disabled");s=r.create(false);r.Rankings_MenuEvent(s,r.ID_LOGIN,q.QM_ACTIVATED);r.Rankings_MenuEvent(s,r.ID_CREATE,q.QM_ACTIVATED);count=count+req(s.actions[0].name=="login" and s.actions[1].name=="signup","login/signup navigation");s=r.create(false);r.Rankings_MenuEvent(s,r.ID_LOGOUT,q.QM_ACTIVATED);count=count+req(s.actions[0].kind=="logout" and s.forcedOff,"logout");s=r.create(false);r.Rankings_MenuEvent(s,r.ID_SPECTATE,q.QM_ACTIVATED);count=count+req(s.actions[0].text=="cmd rank_spectate\n" and s.forcedOff,"spectate command");s=r.create(false);r.Rankings_MenuEvent(s,r.ID_LEAVE,q.QM_ACTIVATED);count=count+req(s.actions[0].text=="disconnect\n","leave command");s=r.create(true);r.UI_RankingsMenu(s,r.QGR_STATUS_NEW);ok=true;for each a in s.actions if a.dispatched then ok=false end if end for;count=count+req(s.pushed and ok,"push and suppressible actions");print("PASS: "+str(count)+" UI rankings contracts");return 0 end function
